import { defineConfig } from "orval";

const input = { target: "../../apps/api/openapi.json" };
const header = () => [
  "Generated by orval from apps/api/openapi.json.",
  "Do not edit by hand: change the API and run `pnpm generate`.",
];

export default defineConfig({
  // TanStack Query hooks and the MSW handlers that mock them, for the browser.
  client: {
    input,
    output: {
      client: "react-query",
      httpClient: "fetch",
      mode: "split",
      target: "src/generated/client/endpoints.ts",
      schemas: "src/generated/client/model",
      clean: true,
      mock: { generators: [{ type: "msw", delay: false }] },
      override: {
        header,
        useDates: false,
        // A hook's data is the response body, so a screen reads `data.status`.
        fetch: { includeHttpResponseReturnType: false },
        mutator: { path: "src/mutator/custom-fetch.ts", name: "customFetch" },
      },
    },
  },
  // Zod schemas for the same operations, for parsing responses. Forms use @heat/contracts instead.
  zod: {
    input,
    output: {
      client: "zod",
      mode: "single",
      target: "src/generated/zod/schemas.ts",
      clean: true,
      override: { header },
    },
  },
});
